code.java:
class Solution {
    public int maxCoins(int[] piles){
        Arrays.sort(piles);
        int rounds=piles.length/3,answer=0;
        for(int index=rounds;index<piles.length;index+=2)answer+=piles[index];
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maxCoins(piles:IntArray):Int{
        piles.sort();
        var answer=0;
        for(index in piles.size/3 until piles.size step 2)answer+=piles[index];
        return answer
    }
}

code.cpp:
class Solution {
    public: int maxCoins(vector<int>& piles){
        sort(piles.begin(),piles.end());
        int answer=0;
        for(int index=piles.size()/3;index<(int)piles.size();index+=2)answer+=piles[index];
        return answer;
    }
};
